"use strict";
const collector = {
  service: "auth-api",
  readService() {
    return this.service;
  },
};
const override = { service: "billing-api" };
const detached = collector.readService;
const locked = collector.readService.bind(collector);
const out = [];
out.push(collector.readService());
out.push(collector.readService.call(override));
try {
  out.push(detached());
} catch (err) {
  out.push(err.name);
}
out.push(locked.call(override));
console.log(out.join("\n"));

