function traceMetricsDispatch() {
  return [];
}

module.exports = { traceMetricsDispatch };

problems.solutionCode:
"use strict";

function traceMetricsDispatch() {
  const outcomes = ["auth-api", "billing-api", "TypeError", "auth-api"];
  return outcomes;
}

module.exports = { traceMetricsDispatch };

problems.trapMutant:
