problems.starterCode:
"use strict";

function bindServiceHandlers(_service, _methodNames) {
  return {};
}

module.exports = { bindServiceHandlers };

problems.solutionCode:
"use strict";

function bindServiceHandlers(service, methodNames) {
  if (service === null || typeof service !== "object") {
    throw new TypeError("service must be a non-null object");
  }
  if (!Array.isArray(methodNames)) {
    throw new TypeError("methodNames must be an array");
  }
  const boundHandlers = {};
  for (const name of methodNames) {
    const candidate = service[name];
    if (typeof candidate !== "function") {
      throw new TypeError(`Missing method: ${String(name)}`);
    }
    boundHandlers[name] = candidate.bind(service);
  }
  return boundHandlers;
}

module.exports = { bindServiceHandlers };

problems.trapMutant:
"use strict";

function bindServiceHandlers(service, methodNames) {
  const handlers = {};
  for (const name of methodNames) {
    handlers[name] = service[name];
  }
  return handlers;
}

module.exports = { bindServiceHandlers };

