class BufferService {
  constructor(prefix) { this.prefix = prefix; this.items = []; }
  pushItem(item) { this.items.push(`${this.prefix}:${item}`); return this.items.length; }
}
const svc = new BufferService('evt');
const { pushItem } = bindServiceHandlers(svc, ['pushItem']);
assert.strictEqual(pushItem('login'), 1);
assert.deepStrictEqual(svc.items, ['evt:login']);

