"use strict";

class InvoiceFormatter {
  constructor(currency, taxRate) {
    this.currency = currency;
    this.taxRate = taxRate;
  }

  formatBatch(items) {
    return items.map(function (item) {
      const totalCents = item.cents * (1 + this.taxRate);
      return `${this.currency} ${(totalCents / 100).toFixed(2)}`;
    });
  }
}

module.exports = { InvoiceFormatter };

problems.solutionCode:
"use strict";

class InvoiceFormatter {
  constructor(currency, taxRate) {
    this.currency = currency;
    this.taxRate = taxRate;
  }

  formatBatch(items) {
    const formatLine = (item) => {
      const totalCents = item.cents * (1 + this.taxRate);
      return `${this.currency} ${(totalCents / 100).toFixed(2)}`;
    };
    return items.map(formatLine);
  }
}

module.exports = { InvoiceFormatter };

